import { readFileSync, writeFileSync } from "fs";
const p = `${process.env.HOME}/Documents/workspace/projects/accessbuddy/ISA.md`;
let s = readFileSync(p, "utf8");
let n = 0;
for (let i = 269; i <= 308; i++) { const a = `- [ ] ISC-${i}:`; if (s.includes(a)) { s = s.replace(a, `- [x] ISC-${i}:`); n++; } }
s = s.replace("ISC-269: Migration 0022 creates", "ISC-269: Migration 0023 creates").replace("ISC-270: Migration 0022 creates", "ISC-270: Migration 0023 creates").replace("ISC-271: Anti: migration 0022 adds", "ISC-271: Anti: migration 0023 adds").replace("migrated through 0022", "migrated through 0023");
const dec = `- 2026-11-23: refined: member emails and merge (ISC-269..309). Migration renumbered 0022 to 0023 after main shipped v1.26.1 with its own 0022 (one pending renewal confirmation per member and season, PR #139); criteria text updated, ids unchanged. The merge coverage test failed on the rebase because of that new unique index, which is the test doing its job; the merge already cancelled the duplicate's same-season pending confirmation, so the index was registered as handled. Independent review (pr-review-toolkit code-reviewer) raised four important findings, all fixed with tests: merge preview returned other clubs' member details; adding an address needed only approve, so email changes on a club admin now need manage admins and are refused for members of another club or global admins (this also tightens the existing edit form); resolution among legacy duplicate emails now prefers the exact stored match, then a real sign-in id, then a membership, then the earliest; merge is refused when either member has records in another club, and a foreign-key failure at the final delete is a distinct non-retryable error. Open for Nick: unverified added addresses can sign in; merge is single-club only; members cannot manage their own addresses; approvers can still remove an admin's additional address.
`;
const a4 = s.indexOf("\n## Changelog");
s = s.slice(0, a4).replace(/\n+$/, "\n") + dec + s.slice(a4);
const cl = `- 2026-11-23 | conjectured: the foreign keys to \`users.id\` listed at design time are the complete set a member merge must handle. refuted_by: main gained a partial unique index over \`attestation_requests(tenant_id, user_id, season)\` while the branch was open, and the merge coverage test failed on the rebase. learned: the set of references to a member is not fixed, so a merge is only safe when a test introspects the live schema for foreign keys and unique indexes and fails on anything unlisted. criterion_now: ISC-301 stands as written and is a permanent gate for any migration that adds a user column or a unique index over one.
`;
const a5 = s.indexOf("\n## Verification");
s = s.slice(0, a5).replace(/\n+$/, "\n") + cl + s.slice(a5);
const ver = `- 2026-11-23 member emails and merge: PR #141 (\`feat/member-emails-and-merge\`, 0be8270, seven commits rebased on v1.26.1) open against main; merge and release left to Nick. ISC-269..308 passed. Local uncached gates on a freshly migrated Postgres (\`ab_member_emails_rebased\`): db:migrate, db:check-drift (PASS, 61 warn, 64 ignored), typecheck, lint (0 errors) and build exit 0; tests shared 34, db 35, web 1,280 passed across 39 files, none skipped. An earlier build exit 1 ("Cannot find module for page: /_document") was my own collision with the QA dev server sharing \`.next\`; the build passes when run alone. New suites: \`member-emails.test.ts\`, \`member-merge.test.ts\` (rollback proven with a blocking foreign key and a full before/after snapshot; coverage test introspects pg_constraint and pg_index), \`member-email-audit-labels.test.ts\`. Browser (headless Chrome, real app and database, 1280px and 375px): email card add, make primary, remove and in-use message; merge search, preview, typed confirmation, result and old-URL redirect; permission cases; long-address dialog fit after fix. Not verified: real Firebase sign-in with an additional address, the global-admin refusal path, behaviour under an RLS-enforcing role, and the production report \`docs/sql/duplicate-emails-report.sql\` (run locally only). ISC-309 deferred to a real-Chrome pass after release.
`;
s = s.replace("\n## Verification\n", "\n## Verification\n" + ver);
s = s.replace(/^updated: .*$/m, "updated: 2026-11-23");
writeFileSync(p, s);
console.log("marked", n);
EOF
